_C = {}


def nf_count(kind, anim):
  return ANIMS[(kind, anim)][0]


def nf_has(kind, anim):
  return (kind, anim) in ANIMS


def nf_frame(kind, anim, i, scale=None, clamp=False, flip=False):
  m = META[kind]
  n, data = ANIMS[(kind, anim)]
  i = max(0, min(n - 1, int(i))) if clamp else int(i) % n
  sc = m['scale'] if scale is None else scale
  k = (kind, anim, i, sc, flip)
  hit = _C.get(k)
  if hit is None:
    raw = _C.get((kind, anim, 'raw'))
    if raw is None:
      raw = _C[(kind, anim, 'raw')] = zlib.decompress(base64.b64decode(data))
    w, h = m['w'], m['h']
    sz = w * h * 4
    s = pygame.image.frombuffer(raw[i * sz:(i + 1) * sz], (w, h), 'RGBA').copy()
    if sc != 1:
      s = pygame.transform.scale(s, (max(1, int(w * sc)), max(1, int(h * sc))))
    if flip:
      s = pygame.transform.flip(s, True, False)
    try:
      s = s.convert_alpha()
    except Exception:
      pass
    ax = int(m['ax'] * sc)
    hit = _C[k] = (s, (s.get_width() - ax) if flip else ax, int(m['ay'] * sc))
  return hit


def nf_bottom(kind, anim, i, scale=None):
  """lowest painted row below the body centre (for landing on the ground)"""
  m = META[kind]
  sc = m['scale'] if scale is None else scale
  bt = m['bottom'][anim]
  return int((bt[max(0, min(len(bt) - 1, int(i)))] - m['ay']) * sc)
